def solve_8_queens():
    solutions = []

    def is_safe(placement, row, col):
        for r, c in enumerate(placement):
            if c == col:                      # same column
                return False
            if abs(r - row) == abs(c - col):  # same diagonal
                return False
        return True

    def backtrack(placement):
        row = len(placement)
        if row == 8:
            solutions.append(placement[:])
            return
        for col in range(8):
            if is_safe(placement, row, col):
                placement.append(col)
                backtrack(placement)
                placement.pop()

    backtrack([])
    return solutions

solutions = solve_8_queens()
print(f"Total solutions found: {len(solutions)}")
print(f"\nFirst solution (col per row): {solutions[0]}")

# Verify the first solution
sol = solutions[0]
print("\nBoard visualization:")
for row in range(8):
    line = ""
    for col in range(8):
        if sol[row] == col:
            line += " Q "
        else:
            line += " . "
    print(f"Row {row}: {line}")

# Double-check no conflicts
def verify(sol):
    for i in range(8):
        for j in range(i+1, 8):
            if sol[i] == sol[j]:
                return False, f"Column conflict: rows {i},{j}"
            if abs(i-j) == abs(sol[i]-sol[j]):
                return False, f"Diagonal conflict: rows {i},{j}"
    return True, "Valid!"

valid, msg = verify(sol)
print(f"\nVerification: {msg}")
